namespace Astrea;

[CreateAssetMenu(fileName = "DodgeCustomTag", menuName = "Data/Battle/Battle Actions/Tags/DodgeCustomTag", order = 0)]
public class DodgeCustomTag : Tag
{
	[SerializeField]
	private DodgeEffect dodgeEffect;

	public override string GetTagDescription()
	{
		return dodgeEffect.GetEffectDescription(EffectsValues.NO_VALUE);
	}
